import {
  myQuestionList,
  questionTodoList,
  questionDoneList,
  hasten,
  listDemand,
  questionDelete,
  processCreate,
  questionSubmit,
  getNextUser,
  questionSend
} from "@/api/ictOperation/index"
import operateForm from './operateForm'
import solveForm from './solveForm'
import questionDetailForm from './questionDetailForm'
import { getDictList } from "@/api/dict";
import questionForm from './questionForm';
import {mapGetters,mapState} from "vuex";

export default {
  components: { operateForm, questionDetailForm, questionForm, solveForm },
  data() {
    return{
      isEdit: false,
      isJiejue: false,
      orderType: '',
      listApi: myQuestionList,
      searchForm: {
        current: 1,
        size: 20
      },
      questionData: [],
      total: 0,
      tableLoading: false,
      questionId: '',
      showOperate: false,
      showSolve: false,
      showDetail: false,
      showUpdateForm: false,
      typeList: [],

      table1: true,
      activeName: 0
    }
  },
  computed: {
    ...mapGetters(["permission", "userDetail"]),
    permissionList() {
      return {
        questionTodo: this.vaildData(this.permission.question_todo, false),
        questionDone: this.vaildData(this.permission.question_done, false),
      };
    },
    isRoleAlias(){
      return this.$store.state.user.userDetail.roleAlias.includes('control_solver')
    }
  },
  mounted() {
    this.getDict()
    this.getList()
  },
  methods: {
    handleExport() {
      //导出
      let types1 = {
        '0': "我的问题",
        '1': "待办任务",
        '2': "已办任务",
        '3': "需求",
        '4': "催办列表",
      }
      let types2 = {
        '0': "my",
        '1': "todo",
        '2': "done",
        '3': "demand",
        '4': "quickly",
      }


      this.$confirm("是否导出数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        this.download(
          "/api/idevelop-control/question/download/export?type="+types2[this.activeName],
          {  },
          types1[this.activeName]+".xlsx"
        )
      });

    },

    // 字典值
    getDict() {
      let dict = ['control_question_type']
      for(let i=0; i<dict.length; i++) {
        getDictList(dict[i]).then(res => {
          if(dict[i] == 'control_question_type') { //问题类型
            this.typeList = res.data
          }
        })
      }
    },

    getList() {
      this.tableLoading = true
      this.listApi(this.searchForm).then(res => {
        this.questionData = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      })
    },
    handleClick(tabs) {
      this.searchForm.current = 1
      if(tabs.name == '0') {
        this.table1 = true
        this.listApi = myQuestionList
      }else if(tabs.name == '1') {
        this.table1 = true
        this.listApi = questionTodoList
      }else if(tabs.name == '2') {
        this.table1 = true
        this.listApi = questionDoneList
      }else if(tabs.name == '3'){
        this.table1 = false
        this.listApi = listDemand
      }else if(tabs.name == '4') { // 催办
        this.table1 = true
        this.listApi = hasten
      }
      this.getList()
    },
    // seeDetail(row) {
    //   this.questionId = row.id
    //   if(row.status == 0) {
    //     this.showUpdateForm = true
    //   }else {
    //     this.showDetail = true
    //   }
    // },

    seeDetail(row, isJiejue) {
      this.orderType = 'see'
      this.questionId = row.id
      if(row.status == 0) {
        this.showUpdateForm = true
      }else {
        this.isJiejue = isJiejue
        this.showDetail = true
      }
    },



    handleEdit(row){
      this.orderType = 'edit'
      // this.isEdit = true
      this.questionId = row.id
      this.showUpdateForm = true
    },
    async handleOperate(row) {
      this.orderType = 'edit'
      this.questionId = row.id

      if(this.isRoleAlias){ // 处理人
        // this.showOperate = true
        this.showDetail = true
      }else{ // 提报人
        this.$confirm("是否确认提交!","提示",{
          confirmButtonText:"确认",
          cancelButtonText:"取消",
          type:"warning"
        }).then( async ()=>{
          if(row.status == 0) {
            let createRes = await processCreate({id: row.id})
          }
          questionSubmit({
            userName: this.userDetail.userName,
            comment: "问题提交",
            id: row.id
          }).then(res => {
            this.submitProcess()
          })
        })

      } 
    },

    async handleSolve(row) {
      this.questionId = row.id
      this.showSolve = true
    },


    delOrder(row) {
      this.$confirm('确定删除该问题?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        questionDelete({id: row.id}).then(() => {
          this.$message({
            message: '删除成功！',
            type: 'success'
          });
          this.getList()
        })
      })
    },
    cuiban(row){
      getNextUser({ businessKey: row.id }).then(res => {
        if(res.data && res.data[0] && res.data[0].users){
          questionSend({ userId: res.data[0].users[0].userId, questionId: row.id }).then(res2 => {
            this.$message({
              message: res2.msg,
              type: 'success'
            });
            this.getList()
          })
        }

      })

    },
    cancel() {
      this.$emit('backQuestion')
    },
    submitProcess() {
      this.showOperate = false
      this.showSolve = false
      this.$message({
        message: '处理成功！',
        type: 'success'
      });
      this.getList()
    },
    typeFormatter(row) {
      return this.selectDictLabel(this.typeList, row.type)
    },
    isResolveFormatter(row){
      if(row.isResolve == 1){
        return '已解决'
      }else{
        return '未解决'
      }
    },
    backQuestion() {
      this.showUpdateForm = false
      this.getList()
    }
  }
}
